const ico=(name,size=17)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${PATHS[name]||PATHS.spark}</svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID?.()||'id-'+Date.now()+'-'+Math.random().toString(36).slice(2);
const dt=new Date(),today=()=>new Date().toISOString().slice(0,10),money=(v,c='OMR')=>`${esc(c)} ${Number(v||0).toLocaleString('en-US',{minimumFractionDigits:3,maximumFractionDigits:3})}`;
const date=v=>v?new Date(v.includes?.('T')?v:v+'T12:00:00').toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'}):'—';
const datetime=v=>v?new Date(v).toLocaleString('en-GB',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}):'—';
const initData=()=>Object.fromEntries(TABLES.map(n=>[n,[]]));
const S={mode:'auth',sb:null,user:null,profile:null,data:initData(),view:'dashboard',query:'',filter:'All',subTab:'',month:new Date(new Date().getFullYear(),new Date().getMonth(),1),selectedDate:today(),mobile:false,sub:null,refreshTimer:null,authPanel:'login',authError:'',busy:false,liveStatus:'Connecting',modal:'',modalId:null};
const savedDemo=()=>{try{return JSON.parse(localStorage.getItem(AUTHKEY))}catch{return null}};
function demoSeed(){const t=today(),people=[{id:'demo-admin',full_name:'Demo Administrator',email:'demo@aaaron.example',department:'management',role:'admin',active:true},{id:'demo-sales',full_name:'Sales Executive',email:'sales@aaaron.example',department:'sales',role:'staff',active:true},{id:'demo-buy',full_name:'Purchase Officer',email:'purchase@aaaron.example',department:'purchase',role:'staff',active:true},{id:'demo-hr',full_name:'HR Coordinator',email:'hr@aaaron.example',department:'hr',role:'staff',active:true}],b=['GEOBIT','MASTER','SEAL COATINGS','WEBER'].map((n,i)=>({id:'demo-brand-'+i,name:n,category:['Waterproofing','Construction Chemicals','Coatings','Construction Materials'][i],active:true}));return {...initData(),profiles:people,brands:b,contacts:[{id:'c1',company:'Example Construction LLC',type:'Customer',contact_person:'Project Engineer',phone:'+968 90000000',email:'',owner_id:'demo-sales',created_at:t},{id:'c2',company:'Sample Industrial Supplies',type:'Supplier',contact_person:'Sales Desk',created_at:t}],enquiries:[{id:'en1',enquiry_no:'ENQ-26-00001',customer:'Example Construction LLC',brand_id:b[0].id,subject:'Waterproof coating – 200 m²',estimated_value:1320,stage:'Quoted',priority:'High',assigned_to:'demo-sales',next_followup:t,created_at:new Date().toISOString()},{id:'en2',enquiry_no:'ENQ-26-00002',customer:'Sample Infrastructure',brand_id:b[3].id,subject:'Tile adhesive and grout',estimated_value:780,stage:'New',priority:'Medium',assigned_to:'demo-sales',next_followup:t,created_at:new Date().toISOString()},{id:'en3',enquiry_no:'ENQ-26-00003',customer:'Example EPC Contracting',brand_id:b[1].id,subject:'Floor repair materials',estimated_value:2600,stage:'Negotiation',priority:'High',assigned_to:'demo-sales',next_followup:t,created_at:new Date().toISOString()}],purchase_orders:[{id:'p1',po_no:'AA-PO-26-00001',vendor:'Example Manufacturer',brand_id:b[0].id,enquiry_id:'en1',currency:'OMR',order_date:t,delivery_date:'',status:'Submitted',subtotal:500,vat_percent:5,total:525,payment_terms:'30% advance, balance before shipment',notes:'Demonstration only',created_by:'demo-buy'}],purchase_order_lines:[{id:'pl1',purchase_order_id:'p1',item_name:'Demo waterproofing material',unit:'Pail',quantity:5,unit_price:100,line_total:500}],meetings:[{id:'m1',title:'Client requirements review',company:'Example Construction LLC',meeting_type:'Customer',starts_at:new Date(Date.now()+86400000).toISOString(),location:'Sohar',status:'Scheduled',assigned_to:'demo-sales',agenda:'Discuss product TDS and quotation'}],tasks:[{id:'t1',title:'Follow up waterproofing quotation',related_type:'Enquiry',related_ref:'ENQ-26-00001',due_date:t,priority:'High',status:'Open',assigned_to:'demo-sales'},{id:'t2',title:'Confirm supplier lead time',related_type:'Purchase',related_ref:'AA-PO-26-00001',due_date:t,priority:'Medium',status:'In Progress',assigned_to:'demo-buy'}],employees:[{id:'e1',employee_no:'DEMO-001',full_name:'Example Employee',department:'Sales',designation:'Sales Executive',work_email:'example@aaaron.example',joining_date:t,employment_status:'Active'}],leave_requests:[]};}
function persistDemo(){if(S.mode==='demo')try{localStorage.setItem(AUTHKEY,JSON.stringify(S.data))}catch(e){console.warn('Demo browser persistence unavailable',e?.message)}}
function configured(){return !!(CFG.supabaseUrl?.startsWith('https://')&&CFG.supabaseAnonKey?.length>30);}
function access(depts){return S.mode==='demo'||S.profile?.role==='admin'||S.profile?.department==='management'||depts.includes(S.profile?.department);}
function approver(){return S.mode==='demo'||S.profile?.role==='admin'||S.profile?.department==='management'||(S.profile?.department==='purchase'&&S.profile?.role==='manager');}
function canView(view){if(['employees'].includes(view))return access(['hr']);if(view==='purchases'||view==='documents'||view==='enquiries'||view==='contacts')return access(['sales','purchase']);if(view==='reports')return access(['sales','purchase','hr']);if(view==='team')return S.mode==='demo'||S.profile?.role==='admin'||S.profile?.department==='management';return true;}
const brandName=id=>S.data.brands.find(b=>b.id===id)?.name||'Unassigned';
const personName=id=>S.data.profiles.find(p=>p.id===id)?.full_name||'Unassigned';
const badge=(txt)=>{let key=String(txt||'').toLowerCase(),kind=/won|approved|received|completed|active|hired|selected/.test(key)?'green':/lost|overdue|urgent|rejected|cancelled|exited/.test(key)?'red':/new|submitted|high|pending|interview|offered/.test(key)?'orange':/quoted|negotiation|qualified|ordered|progress/.test(key)?'blue':'gray';return `<span class="badge ${kind}">${esc(txt||'—')}</span>`};
const btn=(action,label,kind='primary',id='',additional='')=>`<button type="button" class="btn ${kind}" data-action="${action}" ${id?`data-id="${esc(id)}"`:''} ${additional}>${label}</button>`;
const empty=(txt='No records yet',sub='Start by adding a new record.')=>`<div class="empty">${ico('file',33)}<strong>${esc(txt)}</strong>${esc(sub)}</div>`;
const metric=(label,value,foot,icon='chart',color='gold')=>`<div class="metric ${color}"><div class="metric-head"><span class="metric-label">${esc(label)}</span><span class="metric-icon">${ico(icon,19)}</span></div><div class="metric-value">${value}</div><div class="metric-foot">${esc(foot)}</div></div>`;
function toast(msg,bad=false){document.querySelector('.floating-toast')?.remove();const e=document.createElement('div');e.className='floating-toast'+(bad?' error':'');e.textContent=msg;document.body.appendChild(e);setTimeout(()=>e.remove(),4200)}
function field(name,label,type='text',value='',opts={}){let required=opts.required?'required':'',help=opts.help?`<small class="hint">${esc(opts.help)}</small>`:'';let input=type==='textarea'?`<textarea name="${name}" ${required} placeholder="${esc(opts.placeholder||'')}">${esc(value)}</textarea>`:type==='select'?`<select name="${name}" ${required}>${opts.options.map(o=>{let [v,t]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(t)}</option>`}).join('')}</select>`:`<input name="${name}" type="${type}" value="${esc(value)}" ${required} ${opts.min!==undefined?`min="${opts.min}"`:''} ${opts.step?`step="${opts.step}"`:''} placeholder="${esc(opts.placeholder||'')}">`;return `<div class="form-field"><label>${esc(label)}${opts.required?' *':''}</label>${input}${help}</div>`}
const selectOpt=(items,label='Select',emptyOption=true,fn=x=>[x.id,x.name])=>[...(emptyOption?[['',label]]:[]),...items.map(fn)];
const users=(department)=>selectOpt(S.data.profiles.filter(x=>x.active!==false&&(!department||x.department===department)),'Unassigned',true,p=>[p.id,p.full_name+' · '+p.department]);
const brands=()=>selectOpt(S.data.brands,'Select distribution brand',false);
const names=()=>selectOpt(S.data.brands,'All brands',true);
const layoutHead=(title,subtitle,actions='')=>`<div class="headrow"><div><div class="eyebrow">AAARON Commercial Services LLC</div><h1 class="page-title">${esc(title)}</h1><p class="page-desc">${esc(subtitle)}</p></div><div class="head-actions">${actions}</div></div>`;
const dataTable=(head,rows,emptyText='No records found')=>`<div class="table-wrap"><table class="data-table table-inpanel"><thead><tr>${head.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.join(''):`<tr><td colspan="${head.length}">${empty(emptyText,'Try adding a record or changing your filter.')}</td></tr>`}</tbody></table></div>`;
const tr=(...cols)=>`<tr>${cols.map(c=>`<td>${c}</td>`).join('')}</tr>`;
function dataFilter(items,fn){let q=S.query.trim().toLowerCase();return items.filter(x=>!q||fn(x).toLowerCase().includes(q)).filter(x=>S.filter==='All'||(String(x.stage||x.status||x.type||x.brand_id||'')===S.filter))}
function searchToolbar(placeholder='Search records…',extra=''){return `<div class="toolbar"><div class="search-wrap">${ico('search',16)}<input id="searchRecords" autocomplete="off" placeholder="${esc(placeholder)}" value="${esc(S.query)}"></div><div class="stack">${extra}</div></div>`}
let sdkPromise=null;
async function ensureSDK(){
 if(S.sb)return true;
 if(!configured())return false;
 if(!sdkPromise)sdkPromise=new Promise(resolve=>{let tag=document.createElement('script');tag.src='https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2.58.0/dist/umd/supabase.js';tag.async=true;tag.onload=()=>resolve(!!window.supabase?.createClient);tag.onerror=()=>resolve(false);document.head.append(tag);setTimeout(()=>resolve(false),12000)});
 let ready=await sdkPromise;
 if(!ready||!window.supabase?.createClient)return false;
 S.sb=window.supabase.createClient(CFG.supabaseUrl,CFG.supabaseAnonKey,{auth:{autoRefreshToken:true,persistSession:true,detectSessionInUrl:true}});
 return true;
}
async function init(){
 if(configured() && await ensureSDK()){
   S.sb.auth.onAuthStateChange((event,session)=>{
    if(event==='PASSWORD_RECOVERY'){S.mode='auth';S.authPanel='newpassword';S.user=session?.user;renderAuth();return;}
    if(event==='SIGNED_OUT'){S.mode='auth';S.user=null;S.profile=null;S.sub?.unsubscribe();render()}
    else if(event==='SIGNED_IN'&&session?.user&&S.user?.id!==session.user.id){setTimeout(()=>enterLive(session.user),0)}
   });
   const res=await S.sb.auth.getSession();
   if(res.data?.session?.user){await enterLive(res.data.session.user);return}
 }
 render();
}
async function enterLive(user){S.user=user;S.mode='live';S.busy=true;render();try{let r=await S.sb.from('profiles').select('*').eq('id',user.id).single();if(r.error)throw r.error;if(!r.data?.active){S.mode='disabled';render();return}S.profile=r.data;await loadAll();startRealtime();S.busy=false;render()}catch(e){S.mode='error';S.authError=e.message||'Database not yet set up';S.busy=false;render()}}
function enterDemo(){S.sub?.unsubscribe();S.mode='demo';S.user={id:'demo-admin',email:'demo@aaaron.example'};S.profile=demoSeed().profiles[0];S.data=savedDemo()||demoSeed();S.view='dashboard';S.query='';S.filter='All';render()}
async function loadAll(){if(S.mode!=='live')return;const rows=await Promise.all(TABLES.map(async table=>{let r=await S.sb.from(table).select('*').order('created_at',{ascending:false}).limit(1500);return [table,r.error?[]:(r.data||[]),r.error]}));for(let [table,items,err] of rows){if(!err)S.data[table]=items;else if(!/permission denied|policy|permission/i.test(err.message))console.warn('Loading',table,err.message)}S.profile=S.data.profiles.find(p=>p.id===S.user.id)||S.profile;S.liveStatus='Synced';}
function startRealtime(){S.sub?.unsubscribe();S.sub=S.sb.channel('onework-main-'+S.user.id);for(const t of TABLES.filter(x=>x!=='audit_events'))S.sub.on('postgres_changes',{event:'*',schema:'public',table:t},()=>{clearTimeout(S.refreshTimer);S.refreshTimer=setTimeout(async()=>{await loadAll();render()},380)});S.sub.subscribe((v)=>{S.liveStatus=v==='SUBSCRIBED'?'Live sync':'Connecting';if(S.mode==='live')renderTopOnly()})}
async function insert(table,data){if(S.mode==='demo'){let rec={id:uid(),created_at:new Date().toISOString(),...data};if(table==='quotations')rec.quote_no=`QUO-26-${String(S.data.quotations.length+1).padStart(5,'0')}${rec.revision>1?'-R'+rec.revision:''}`;if(table==='opportunities')rec.opportunity_no=`OPP-${String(S.data.opportunities.length+1).padStart(6,'0')}`;if(table==='projects')rec.project_no=`PRJ-${String(S.data.projects.length+1).padStart(5,'0')}`;if(table==='contacts')rec.customer_no=`CUS-${String(S.data.contacts.length+1).padStart(6,'0')}`;if(table==='enquiries')rec.enquiry_no=`ENQ-26-${String(S.data.enquiries.length+1).padStart(5,'0')}`;S.data[table].unshift(rec);persistDemo();return rec}let {data:d,error}=await S.sb.from(table).insert(data).select().single();if(error)throw error;await loadAll();return d}
async function update(table,id,values){if(S.mode==='demo'){let rec=S.data[table].find(x=>x.id===id);if(!rec)throw Error('Record not found');Object.assign(rec,values);persistDemo();return rec}let r=await S.sb.from(table).update(values).eq('id',id).select().single();if(r.error)throw r.error;await loadAll();return r.data}
async function createPO(header,lines){if(S.mode==='demo'){let id=uid(),subtotal=lines.reduce((s,l)=>s+Number(l.quantity)*Number(l.unit_price),0),vat=Number(header.vat_percent)||0;let rec={id,po_no:`AA-PO-26-${String(S.data.purchase_orders.length+1).padStart(5,'0')}`,status:'Draft',subtotal,total:subtotal*(1+vat/100),created_by:S.user.id,order_date:today(),...header};S.data.purchase_orders.unshift(rec);S.data.purchase_order_lines.push(...lines.map(l=>({id:uid(),purchase_order_id:id,line_total:Number(l.quantity)*Number(l.unit_price),...l})));persistDemo();return rec}let r=await S.sb.rpc('aaaron_create_purchase_order',{p_header:header,p_lines:lines});if(r.error)throw r.error;await loadAll();return S.data.purchase_orders.find(x=>x.id===r.data)}
async function setPO(id,status){if(S.mode==='demo'){let p=S.data.purchase_orders.find(x=>x.id===id);p.status=status;if(status==='Approved'){p.approved_by=S.user.id;p.approved_at=new Date().toISOString()}persistDemo();return}let r=await S.sb.rpc('aaaron_set_po_status',{p_id:id,p_status:status});if(r.error)throw r.error;await loadAll()}
async function reviewLeave(id,status){if(S.mode==='demo'){S.data.leave_requests.find(x=>x.id===id).status=status;persistDemo();return}let r=await S.sb.rpc('aaaron_review_leave',{p_id:id,p_status:status});if(r.error)throw r.error;await loadAll()}
async function uploadDocument(meta,file){if(S.mode==='demo'){let r={id:uid(),...meta,file_name:file.name,file_size:file.size,storage_path:'DEMO_ONLY',uploaded_by:S.user.id,created_at:new Date().toISOString()};S.data.technical_documents.unshift(r);persistDemo();toast('Demo metadata saved; file content is NOT stored in demo. Use Live mode for actual cloud uploads.');return}if(!file)throw Error('Select a file');if(file.size>20*1024*1024)throw Error('File exceeds 20 MB');const ext=file.name.split('.').pop().toLowerCase();if(!['pdf','png','jpg','jpeg','doc','docx','xls','xlsx'].includes(ext))throw Error('Only PDF, image, Word or Excel files are accepted');let path=`${S.user.id}/${meta.brand_id}/${uid()}.${ext}`;let r=await S.sb.storage.from('aaaron-tds').upload(path,file,{contentType:file.type||'application/octet-stream',upsert:false});if(r.error)throw r.error;try{await insert('technical_documents',{...meta,file_name:file.name,file_size:file.size,mime_type:file.type,storage_path:path,uploaded_by:S.user.id})}catch(e){await S.sb.storage.from('aaaron-tds').remove([path]);throw e}}
async function openDocument(id){const d=S.data.technical_documents.find(x=>x.id===id);if(!d)return;if(S.mode==='demo'){toast('The demo does not upload files. Connect Supabase for private file storage.');return}let res=await S.sb.storage.from('aaaron-tds').createSignedUrl(d.storage_path,120);if(res.error)throw res.error;window.open(res.data.signedUrl,'_blank','noopener,noreferrer')}
function renderTopOnly(){let e=document.querySelector('#syncStatus');if(e)e.innerHTML=`<span class="dot ${S.mode==='demo'?'demo':''}"></span><span class="connection-label">${S.mode==='demo'?'Demo · Local':esc(S.liveStatus)}</span>`}
function render(){let el=document.getElementById('app');if(!el)return;if(S.mode==='auth'||S.mode==='error'||S.mode==='disabled'){renderAuth();return}if(S.busy){el.innerHTML=`<div class="loading"><img src="${A.icon}" width="82" alt="AAARON"><p>Syncing secure workspace…</p></div>`;return}if(!canView(S.view))S.view='dashboard';el.innerHTML=`<div class="layout"><aside class="sidebar">${sidebar()}</aside><div class="scrim" data-action="menu"></div><main class="main"><header class="topbar"><div class="stack"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Open menu">${ico('menu',22)}</button><div><div class="crumb">AAARON OneWork CRM</div><div class="top-title">${esc(TITLE[S.view])}</div></div></div>${OW.searchBox?OW.searchBox():''}<div class="top-right"><div class="top-bubble" id="syncStatus"><span class="dot ${S.mode==='demo'?'demo':''}"></span><span class="connection-label">${S.mode==='demo'?'Demo · Local':esc(S.liveStatus)}</span></div><div class="user-flag"><div class="avatar">${esc((S.profile?.full_name||'A').trim().charAt(0))}</div><div class="user-info">${esc(S.profile?.full_name||'User')}<small>${esc(S.profile?.department||'')} · ${esc(S.profile?.role||'')}</small></div></div></div></header>${S.mode==='demo'?'<div class="mode-banner">Demo mode — all names and figures are fictional and saved only on this device. Nothing is shared with other employees. Connect Supabase to go live.</div>':''}<div class="page">${view()}</div></main></div><div id="overlay"></div>`;S.mobile=false}
function sidebar(){return `<div class="brand-area"><img class="brand-logo" src="${A.wordmarkRev}" alt="AAARON"><div class="brand-caption">OneWork CRM<br><span>Commercial Services LLC</span></div><div class="build-pill">Build 4.0 · ${S.mode==='demo'?'Demo mode':'Database connected'}</div></div><div class="side-inner">${NAV.map(([heading,links])=>{let visible=links.filter(([id])=>canView(id));if(!visible.length)return'';return `<div class="nav-heading">${heading}</div>${visible.map(([id,lab,icon])=>`<button class="nav-item ${S.view===id?'active':''}" data-nav="${id}" ${S.view===id?'aria-current="page"':''}>${ico(icon,17)}<span>${lab}</span>${id==='tasks'&&S.data.tasks.filter(x=>x.status!=='Completed'&&x.due_date&&x.due_date<=today()).length?`<span class="nav-counter">${S.data.tasks.filter(x=>x.status!=='Completed'&&x.due_date&&x.due_date<=today()).length}</span>`:''}</button>`).join('')}`}).join('')}</div><div class="sidebar-foot"><div class="stack"><div class="avatar">${esc((S.profile?.full_name||'A')[0])}</div><div style="min-width:0"><strong>${esc(S.profile?.full_name||'Team')}</strong><div class="mini">${S.mode==='demo'?'Preview workspace':'Secure company workspace'}</div></div></div><button class="nav-item" data-action="logout" style="margin:12px 0 0;padding:8px 0">${ico('logout',15)} ${S.mode==='demo'?'Exit demo':'Sign out'}</button></div>`}
function renderAuth(){const card=S.authPanel==='newpassword'?`<h2>Set your new password</h2><p>Choose a strong new password for your AAARON account.</p><form id="authForm">${field('password','New password','password','',{required:true})}${field('confirm','Confirm new password','password','',{required:true})}<button class="btn primary" type="submit">Update password</button></form>`:S.mode==='disabled'?`<h2>Access temporarily disabled</h2><p>Please contact your AAARON system administrator to activate your staff account.</p><button class="btn" data-action="auth-mode" data-value="newpassword">Set or change password</button> <button class="btn" data-action="logout">Sign out</button>`:S.mode==='error'?`<h2>Database needs setup</h2><p>The account is authenticated but the shared tables or access setup are not ready.</p><div class="auth-error">${esc(S.authError)}</div><button class="btn primary" data-action="retry">Try again</button><button class="btn" data-action="logout">Sign out</button>`:`<div class="auth-co">AAARON Commercial Services LLC</div><h2>${S.authPanel==='signup'?'Create your staff account':S.authPanel==='forgot'?'Reset your password':'Welcome back'}</h2><p>${S.authPanel==='signup'?'Sign-up may require administrator approval and an enabled invitation setting.':S.authPanel==='forgot'?'Receive a secure reset link by email.':'Sign in to your company’s shared workspace.'}</p>${S.authError?`<div class="auth-error">${esc(S.authError)}</div>`:''}<form id="authForm">${S.authPanel==='signup'?field('full_name','Your full name','text','',{required:true}):''}${field('email','Work email address','email','',{required:true,placeholder:'name@company.com'})}${S.authPanel!=='forgot'?field('password','Password','password','',{required:true}):''}<button type="submit" class="btn gold">${S.authPanel==='signup'?'Create account':S.authPanel==='forgot'?'Send reset link':'Sign in securely'} ${ico('right',15)}</button></form><div class="auth-links"><button data-action="auth-mode" data-value="${S.authPanel==='login'?'forgot':'login'}">${S.authPanel==='login'?'Forgot password?':'Back to sign in'}</button><button data-action="auth-mode" data-value="${S.authPanel==='signup'?'login':'signup'}">${S.authPanel==='signup'?'Existing account':'Request account'}</button></div><div class="auth-demo"><button class="btn primary" data-action="demo">${ico('spark',16)} Explore interactive demo</button><div class="hint" style="text-align:center;margin-top:10px">${configured()?'Live cloud configuration detected.':'Team login needs setup: see GO_LIVE_SETUP.md'}</div></div>`;
document.getElementById('app').innerHTML=`<div class="auth-screen"><div class="auth-intro"><div class="plate"><img src="${A.wordmarkRev}" alt="AAARON Commercial Services LLC"></div><div class="copy"><h1>One company. One workspace.</h1><p>Enquiries, quotations, projects, purchasing, technical documents, meetings, HR and management reports in one secure AAARON platform.</p><div class="auth-tags"><span>Sales CRM</span><span>Purchasing</span><span>28 reports</span><span>Live team sync</span></div></div><img class="auth-deco" src="${A.mark}" alt=""></div><div class="auth-side"><div class="auth-card">${card}</div></div></div>`}
function view(){switch(S.view){case'dashboard':return dashboard();case'enquiries':return enquiries();case'contacts':return contacts();case'purchases':return purchases();case'documents':return documents();case'meetings':return meetings();case'tasks':return tasks();case'employees':return employees();case'leaves':return leaves();case'reports':return reports();case'team':return team();default:return dashboard()}}
function dashboard(){let en=S.data.enquiries,po=S.data.purchase_orders,ts=S.data.tasks,meet=S.data.meetings;let active=en.filter(x=>!['Won','Lost'].includes(x.stage)),pipeline=active.reduce((s,x)=>s+Number(x.estimated_value||0),0),overdue=ts.filter(x=>!['Completed','Cancelled'].includes(x.status)&&x.due_date&&x.due_date<today()),upcoming=meet.filter(x=>x.starts_at&&new Date(x.starts_at)>=new Date()&&x.status==='Scheduled').sort((a,b)=>new Date(a.starts_at)-new Date(b.starts_at)).slice(0,4);let count=Object.fromEntries(['New','Qualified','Quoted','Negotiation','Won','Lost'].map(x=>[x,en.filter(y=>y.stage===x).length]));return `${layoutHead(`Good ${new Date().getHours()<12?'morning':new Date().getHours()<17?'afternoon':'evening'}, ${S.profile?.full_name?.split(' ')[0]||'Team'} 👋`,'Here’s what is happening across AAARON today.',`<div class="stack">${access(['sales'])?btn('new-enquiry',ico('plus',15)+' New enquiry','gold'):''}${btn('new-task',ico('plus',15)+' Follow-up')}</div>`)}<div class="metric-grid">${metric('Active enquiries',active.length,'Across all assigned brands','briefcase','gold')}${metric('Sales pipeline',money(pipeline),'Indicative value, in OMR','chart','blue')}${metric('Purchase orders',po.length,`${po.filter(x=>x.status==='Submitted').length} waiting for approval`,'box','green')}${metric('Overdue follow-ups',overdue.length,`${ts.filter(x=>x.status==='Open').length} open tasks`,'clock','purple')}</div><div class="columns"><div><div class="panel"><div class="panel-header"><div><div class="panel-title">Recent sales enquiries</div><div class="panel-sub">Your latest shared pipeline activity</div></div><button class="btn sm" data-nav="enquiries">View all ${ico('right',13)}</button></div>${dataTable(['Reference / Customer','Brand','Value','Stage'],en.slice(0,5).map(x=>tr(`<strong>${esc(x.enquiry_no)}</strong><div class="hint">${esc(x.customer)}</div>`,esc(brandName(x.brand_id)),money(x.estimated_value),badge(x.stage))), 'No enquiries entered')}</div><div class="panel"><div class="panel-header"><div><div class="panel-title">Open follow-up actions</div><div class="panel-sub">Stay ahead of due dates and outstanding tasks</div></div><button class="btn sm" data-nav="tasks">View tasks</button></div><div class="entry-list">${ts.filter(x=>!['Completed','Cancelled'].includes(x.status)).slice(0,5).map(x=>`<div class="entry"><div class="entry-mark ${x.due_date<today()?'':'blue'}">${ico('check',17)}</div><div class="entry-main"><strong>${esc(x.title)}</strong><small>${esc(personName(x.assigned_to))} · ${esc(x.related_type||'General')}</small></div><div class="entry-time">${date(x.due_date)}<div style="margin-top:5px">${badge(x.priority)}</div></div></div>`).join('')||empty('All caught up','No outstanding follow-ups to show.')}</div></div></div><div><div class="panel"><div class="panel-header"><div><div class="panel-title">Enquiry pipeline</div><div class="panel-sub">Distribution across sales stages</div></div>${ico('chart',17)}</div><div class="panel-body">${Object.entries(count).map(([k,v])=>`<div class="progress-item"><div class="progress-info"><strong>${k}</strong><span>${v} enquiry${v!==1?'ies':''}</span></div><div class="progress-track"><div class="progress-fill" style="width:${en.length?100*v/en.length:0}%;background:${k==='Won'?'#55b996':k==='Lost'?'#ce7686':undefined||'#e7ad2c'}"></div></div></div>`).join('')}</div></div><div class="panel"><div class="panel-header"><div><div class="panel-title">Upcoming meetings</div><div class="panel-sub">Stay prepared for each client touchpoint</div></div>${ico('calendar',17)}</div><div class="entry-list">${upcoming.map(x=>`<div class="entry"><div class="entry-mark blue">${ico('calendar',17)}</div><div class="entry-main"><strong>${esc(x.title)}</strong><small>${esc(x.company||x.location||'Internal')}</small></div><div class="entry-time">${datetime(x.starts_at)}</div></div>`).join('')||empty('No meetings ahead','Schedule a meeting to see it here.')}</div><div class="panel-actions" style="padding:10px 19px 17px">${btn('new-meeting',ico('plus',14)+' Schedule meeting','sm')}</div></div></div></div>`}
function enquiries(){let arr=dataFilter(S.data.enquiries,x=>[x.enquiry_no,x.customer,x.subject,brandName(x.brand_id)].join(' '));let fs=['All','New','Qualified','Quoted','Negotiation','Won','Lost'];return `${layoutHead('Sales enquiries','Capture customer RFQs and track every opportunity from first contact to order.',access(['sales'])?btn('new-enquiry',ico('plus',15)+' New enquiry','gold'):'')}${searchToolbar('Search reference, customer, requirement…',`<select class="filter-select" id="filterRecords">${fs.map(x=>`<option ${S.filter===x?'selected':''}>${x}</option>`).join('')}</select>${btn('export',ico('download',14)+' Export CSV','sm')}`)}<div class="panel">${dataTable(['Enquiry / Requirement','Distribution brand','Estimated value','Owner / Next follow-up','Stage',''],arr.map(x=>tr(`<strong>${esc(x.enquiry_no)}</strong><div>${esc(x.customer)}</div><div class="hint truncate">${esc(x.subject)}</div>`,esc(brandName(x.brand_id)),money(x.estimated_value),`<strong>${esc(personName(x.assigned_to))}</strong><div class="hint">${date(x.next_followup)}</div>`,badge(x.stage),access(['sales'])?`<button class="icon-btn" data-action="edit-enquiry" data-id="${esc(x.id)}" aria-label="Edit">${ico('edit',15)}</button>`:'')),'No enquiries match these filters')}<div class="pagination-note">Showing ${arr.length} enquiries</div></div>`}
function contacts(){let arr=dataFilter(S.data.contacts,x=>[x.company,x.contact_person,x.email,x.phone].join(' '));return `${layoutHead('Customers & suppliers','One searchable, shared contact directory for the commercial team.',access(['sales','purchase'])?btn('new-contact',ico('plus',15)+' Add contact','gold'):'')}${searchToolbar('Find customer, vendor, person or phone…',btn('export',ico('download',14)+' Export CSV','sm'))}<div class="panel">${dataTable(['Company / Organization','Type','Contact person','Phone','Email',''],arr.map(x=>tr(`<strong>${esc(x.company)}</strong>`,badge(x.type),esc(x.contact_person),esc(x.phone),esc(x.email),`<button class="icon-btn" data-action="edit-contact" data-id="${esc(x.id)}">${ico('edit',15)}</button>`)))}</div>`}
function purchases(){let arr=dataFilter(S.data.purchase_orders,x=>[x.po_no,x.vendor,brandName(x.brand_id),x.status].join(' '));let opts=['All','Draft','Submitted','Approved','Ordered','Partially Received','Received','Cancelled'];return `${layoutHead('Purchase orders','Structured purchase orders, line items and auditable approvals.',access(['purchase'])?btn('new-po',ico('plus',15)+' Create purchase order','gold'):'')}${searchToolbar('Search PO number, supplier, status…',`<select class="filter-select" id="filterRecords">${opts.map(x=>`<option ${S.filter===x?'selected':''}>${x}</option>`).join('')}</select>${btn('export',ico('download',14)+' Export CSV','sm')}`)}<div class="panel">${dataTable(['PO number / Supplier','Brand','Order date','Amount','Approval status','Actions'],arr.map(x=>tr(`<strong>${esc(x.po_no)}</strong><div class="hint">${esc(x.vendor)}</div>`,esc(brandName(x.brand_id)),date(x.order_date),`<strong>${money(x.total,x.currency)}</strong>`,badge(x.status),`<div class="stack"><button class="btn sm" data-action="po-details" data-id="${esc(x.id)}">${ico('external',13)} Details</button><button class="icon-btn" data-action="print-po" data-id="${esc(x.id)}" title="Print PO">${ico('printer',15)}</button></div>`)))}</div>${S.mode==='live'?'<div class="notice info">PO amounts and approval steps are validated on the server. Purchase staff cannot approve their own orders unless they hold an authorized approval role.</div>':''}`}
function documents(){let arr=S.data.technical_documents.filter(x=>(S.filter==='All'||x.brand_id===S.filter)).filter(x=>[x.title,x.product,x.file_name,x.document_type,brandName(x.brand_id)].join(' ').toLowerCase().includes(S.query.toLowerCase()));return `${layoutHead('Brand technical library','Centralized, permission-controlled TDS, SDS, catalogues and certifications.',access(['sales','purchase'])?btn('new-doc',ico('upload',15)+' Upload document','gold'):'')}<div class="notice info">Brand documents are stored in a <strong>private Supabase Storage bucket</strong> in Live mode. Files are opened with temporary, signed links (2 minutes). The demo saves metadata only.</div><div class="brand-filter">${[['All','All brands'],...S.data.brands.map(x=>[x.id,x.name])].map(([id,lab])=>`<button class="chip ${S.filter===id?'active':''}" data-action="brand-filter" data-id="${esc(id)}">${esc(lab)} <span style="opacity:.6">${S.data.technical_documents.filter(d=>id==='All'||d.brand_id===id).length}</span></button>`).join('')}</div>${searchToolbar('Search product, revision, type, document title…',btn('new-brand',ico('plus',13)+' New brand','sm', '', access(['purchase'])?'':'disabled'))}<div class="grid3">${arr.map(d=>`<div class="doc-card"><div class="doc-icon">${ico('file',20)}</div><div class="doc-body"><strong>${esc(d.title)}</strong><small>${esc(brandName(d.brand_id))} · ${esc(d.product||d.document_type)}</small><div class="stack" style="margin-top:10px">${badge(d.document_type)} <span class="hint">${esc(d.version||'Current')}</span></div><small style="overflow-wrap:anywhere">${esc(d.file_name||'Document')}</small><button class="btn sm" style="margin-top:10px" data-action="open-doc" data-id="${esc(d.id)}">${ico('external',13)} Open file</button></div></div>`).join('')||`<div style="grid-column:1/-1" class="panel">${empty('No documents in this brand','Upload a product TDS or catalogue to build the library.')}</div>`}</div>`}
function meetings(){let y=S.month.getFullYear(),m=S.month.getMonth(),first=new Date(y,m,1).getDay(),offset=(first+6)%7,total=new Date(y,m+1,0).getDate(),months=S.month.toLocaleDateString('en-GB',{month:'long',year:'numeric'}),dayEvents=S.data.meetings.filter(x=>x.starts_at&&new Date(x.starts_at).toLocaleDateString('en-CA')===S.selectedDate);let cells=[...Array(offset).fill(null),...Array.from({length:total},(_,i)=>i+1)];while(cells.length%7)cells.push(null);return `${layoutHead('Meetings & calendar','Plan customer visits, supplier calls and internal review meetings.',btn('new-meeting',ico('plus',15)+' Schedule meeting','gold'))}<div class="columns"><div class="panel"><div class="panel-header"><div><div class="panel-title">${esc(months)}</div><div class="panel-sub">Select a day to see its meetings</div></div><div class="stack"><button class="icon-btn" data-action="prev-month">${ico('left',18)}</button><button class="icon-btn" data-action="next-month">${ico('right',18)}</button></div></div><div class="calendar">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(x=>`<div class="cal-label">${x}</div>`).join('')}${cells.map(n=>{if(!n)return'<div class="cal-day muted"></div>';let day=`${y}-${String(m+1).padStart(2,'0')}-${String(n).padStart(2,'0')}`,events=S.data.meetings.filter(x=>x.starts_at&&new Date(x.starts_at).toLocaleDateString('en-CA')===day);return `<button class="cal-day ${day===today()?'today':''} ${day===S.selectedDate?'selected':''}" data-action="select-date" data-id="${day}"><span class="cal-date">${n}</span>${events.slice(0,2).map(x=>`<span class="cal-event ${x.meeting_type==='Internal'?'gold':''}">${esc(x.title)}</span>`).join('')}${events.length>2?`<span class="hint">+${events.length-2} more</span>`:''}</button>`}).join('')}</div></div><div class="panel"><div class="panel-header"><div><div class="panel-title">${date(S.selectedDate)}</div><div class="panel-sub">Scheduled appointments</div></div>${ico('calendar',17)}</div><div class="entry-list">${dayEvents.map(x=>`<div class="entry"><div class="entry-mark blue">${ico('clock',17)}</div><div class="entry-main"><strong>${esc(x.title)}</strong><small>${esc(x.company||x.location||'Internal')} · ${esc(personName(x.assigned_to))}</small></div><div class="entry-time">${datetime(x.starts_at)}<div style="margin-top:6px">${badge(x.status)}</div></div></div>`).join('')||empty('No appointments this day','Schedule a meeting using the button above.')}</div></div></div><div class="panel"><div class="panel-header"><div class="panel-title">All meetings</div></div>${dataTable(['Meeting / Company','Schedule','Owner','Status',''],S.data.meetings.slice().sort((a,b)=>new Date(b.starts_at)-new Date(a.starts_at)).slice(0,20).map(x=>tr(`<strong>${esc(x.title)}</strong><div class="hint">${esc(x.company||'')}</div>`,datetime(x.starts_at),esc(personName(x.assigned_to)),badge(x.status),`<button class="icon-btn" data-action="edit-meeting" data-id="${x.id}">${ico('edit',15)}</button>`)))}</div>`}
function tasks(){let arr=dataFilter(S.data.tasks,x=>[x.title,x.related_type,x.related_ref,personName(x.assigned_to)].join(' ')),options=['All','Open','In Progress','Completed','Cancelled'];return `${layoutHead('Tasks & follow-ups','Every pending quote, supply commitment and team action in one place.',btn('new-task',ico('plus',15)+' New task','gold'))}<div class="metric-grid">${metric('Open tasks',S.data.tasks.filter(x=>x.status==='Open').length,'Not yet started','check')}${metric('In progress',S.data.tasks.filter(x=>x.status==='In Progress').length,'Being worked on','clock','blue')}${metric('Overdue',S.data.tasks.filter(x=>x.due_date&&x.due_date<today()&&!['Completed','Cancelled'].includes(x.status)).length,'Needs immediate attention','alert','purple')}${metric('Completed',S.data.tasks.filter(x=>x.status==='Completed').length,'Finished actions','check','green')}</div>${searchToolbar('Search tasks, references, owners…',`<select class="filter-select" id="filterRecords">${options.map(x=>`<option ${S.filter===x?'selected':''}>${x}</option>`).join('')}</select>${btn('export',ico('download',14)+' Export CSV','sm')}`)}<div class="panel">${dataTable(['Action / Reference','Assigned to','Due date','Priority','Status',''],arr.map(x=>tr(`<strong>${esc(x.title)}</strong><div class="hint">${esc(x.related_type)} · ${esc(x.related_ref||'General')}</div>`,esc(personName(x.assigned_to)),`<span style="color:${x.due_date<today()&&x.status!=='Completed'?'#c44455':'inherit'}">${date(x.due_date)}</span>`,badge(x.priority),badge(x.status),`<button class="icon-btn" data-action="edit-task" data-id="${x.id}">${ico('edit',15)}</button>`)))}</div>`}
function employees(){let arr=dataFilter(S.data.employees,x=>[x.employee_no,x.full_name,x.department,x.designation].join(' '));return `${layoutHead('Employee master','Maintain AAARON employee details, departments and employment status.',btn('new-employee',ico('plus',15)+' Add employee','gold'))}${searchToolbar('Search staff number, employee, department…',btn('export',ico('download',14)+' Export CSV','sm'))}<div class="notice info">Employee records are visible to authorized HR and Management users only. Passwords, identity numbers and salaries are intentionally not stored in this version.</div><div class="panel">${dataTable(['Employee','Department','Designation','Joining date','Status',''],arr.map(x=>tr(`<strong>${esc(x.full_name)}</strong><div class="hint">${esc(x.employee_no)}</div>`,esc(x.department),esc(x.designation),date(x.joining_date),badge(x.employment_status),`<button class="icon-btn" data-action="edit-employee" data-id="${x.id}">${ico('edit',15)}</button>`)))}</div>`}
function leaves(){let arr=S.data.leave_requests.filter(x=>S.filter==='All'||x.status===S.filter);let opts=['All','Pending','Approved','Rejected'];return `${layoutHead('Leave management','Submit leave applications and manage HR approvals in the same system.',btn('new-leave',ico('plus',15)+' Request leave','gold'))}${searchToolbar('Search leave entries…',`<select class="filter-select" id="filterRecords">${opts.map(x=>`<option ${S.filter===x?'selected':''}>${x}</option>`).join('')}</select>`)}<div class="panel">${dataTable(['Employee','Leave type','Period','Reason','Status','Actions'],arr.map(x=>tr(`<strong>${esc(personName(x.employee_id))}</strong>`,esc(x.leave_type),`${date(x.start_date)} – ${date(x.end_date)}`,esc(x.reason),badge(x.status),x.status==='Pending'&&access(['hr'])?`<div class="stack">${btn('approve-leave','Approve','sm',x.id)}${btn('reject-leave','Reject','sm danger',x.id)}</div>`:'—')))}</div>`}
function reports(){let en=S.data.enquiries,po=S.data.purchase_orders,ts=S.data.tasks,br=S.data.brands;let stats=br.map(x=>({name:x.name,count:en.filter(e=>e.brand_id===x.id).length,value:en.filter(e=>e.brand_id===x.id).reduce((s,e)=>s+Number(e.estimated_value||0),0),docs:S.data.technical_documents.filter(d=>d.brand_id===x.id).length,orders:po.filter(p=>p.brand_id===x.id).length}));let max=Math.max(1,...stats.map(x=>x.count));return `${layoutHead('Analytics & business reports','Brand-wise sales, purchases and workload; export current records to CSV.',`<div class="stack">${btn('export',ico('download',14)+' Export this report','gold')}${btn('print-report',ico('printer',14)+' Print','sm')}</div>`)}<div class="metric-grid">${metric('Total enquiry value',money(en.reduce((s,x)=>s+Number(x.estimated_value||0),0)),'Illustrative deal value, OMR','chart')}${metric('Total PO value',money(po.filter(x=>x.currency==='OMR').reduce((s,x)=>s+Number(x.total||0),0)),'OMR orders only','box','blue')}${metric('Registered brands',br.length,'Brand-separated product TDS','file','green')}${metric('Registered employees',S.data.employees.length,'HR restricted records','users','purple')}</div><div class="columns equal"><div class="panel"><div class="panel-header"><div class="panel-title">Enquiries by distribution brand</div></div><div class="panel-body"><div class="report-bars">${stats.map(x=>`<div class="report-bar"><strong style="font-size:11px">${x.count}</strong><div class="report-bar-rect" style="height:${x.count/max*90}px"></div><span title="${esc(x.name)}">${esc(x.name)}</span></div>`).join('')}</div></div></div><div class="panel"><div class="panel-header"><div class="panel-title">Order status breakdown</div></div><div class="panel-body">${['Draft','Submitted','Approved','Ordered','Received'].map(s=>`<div class="progress-item"><div class="progress-info"><strong>${s}</strong><span>${po.filter(x=>x.status===s).length}</span></div><div class="progress-track"><div class="progress-fill" style="width:${po.length?100*po.filter(x=>x.status===s).length/po.length:0}%"></div></div></div>`).join('')}</div></div></div><div class="panel"><div class="panel-header"><div class="panel-title">Brand-wise commercial summary</div></div>${dataTable(['Brand','Enquiries','Pipeline value (OMR)','POs','TDS files'],stats.map(x=>tr(`<strong>${esc(x.name)}</strong>`,x.count,money(x.value),x.orders,x.docs)))}</div><div class="notice info">Reports are based on records your account is permitted to read. Totals across different PO currencies are not mixed; OMR order values are shown separately.</div>`}
function team(){let editable=S.mode==='demo'||S.profile?.role==='admin';return `${layoutHead('Team access & permissions','Department isolation, user roles, cloud setup and operational audit.',`<div class="stack">${btn('refresh',ico('clock',14)+' Refresh','sm')}${S.mode==='demo'?btn('reset-demo',ico('spark',14)+' Reset demo','sm danger'):''}</div>`)}<div class="notice info">${S.mode==='demo'?'This is a preview. In Live mode, users authenticate with Supabase and permissions are enforced by PostgreSQL Row Level Security.':'Live mode: new users must first be created or invited through your Supabase Authentication console (or self-signup if enabled). Admins can manage access below.'}</div><div class="panel"><div class="panel-header"><div><div class="panel-title">Authorized staff accounts</div><div class="panel-sub">Roles: Admin, Department Manager or Staff</div></div>${ico('shield',18)}</div>${dataTable(['Employee','Email','Department','Role','Access',''],S.data.profiles.map(x=>tr(`<strong>${esc(x.full_name)}</strong>`,esc(x.email),esc(x.department),badge(x.role),badge(x.active?'Active':'Disabled'),editable?`<button class="icon-btn" data-action="edit-profile" data-id="${esc(x.id)}">${ico('edit',15)}</button>`:'—')))}</div><div class="columns equal"><div class="panel"><div class="panel-header"><div class="panel-title">Department visibility</div></div><div class="panel-body"><p style="font-size:12px;line-height:2;color:#76849a"><strong>Sales:</strong> Enquiries, customers, brand documents, meeting tasks.<br><strong>Purchase:</strong> Suppliers, purchase orders, brand documents; read enquiries.<br><strong>HR:</strong> Employee records, leave approvals; assigned meetings and tasks.<br><strong>Management/Admin:</strong> Cross-department reporting, approvals and oversight.</p></div></div><div class="panel"><div class="panel-header"><div class="panel-title">Cloud & security status</div></div><div class="panel-body"><p style="font-size:12px;line-height:2;color:#76849a"><strong>Connection:</strong> ${S.mode==='demo'?'Local demonstration':esc(S.liveStatus)}<br><strong>Storage:</strong> ${S.mode==='demo'?'Metadata only':'Private Supabase bucket'}<br><strong>Sync:</strong> ${S.mode==='demo'?'Browser only':'Authorized realtime subscriptions'}<br><strong>Audit trail:</strong> ${S.mode==='demo'?'Not recorded':'Database event history'}</p></div></div></div>${S.data.audit_events.length?`<div class="panel"><div class="panel-header"><div class="panel-title">Recent audit activity</div></div>${dataTable(['Table','Action','Staff','Time'],S.data.audit_events.slice(0,20).map(x=>tr(esc(x.table_name),badge(x.operation),esc(personName(x.actor_id)),datetime(x.created_at))))}</div>`:''}`}
const TYPE_TABLE={enquiry:'enquiries',contact:'contacts',po:'purchase_orders',doc:'technical_documents',meeting:'meetings',task:'tasks',employee:'employees',leave:'leave_requests',profile:'profiles',brand:'brands'};
function modalOpen(type,id=null){S.modal=type;S.modalId=id;const row=id?S.data[TYPE_TABLE[type]]?.find(x=>x.id===id)||{}:{};let content='',title='';
 if(type==='enquiry'){title=id?'Update enquiry':'New sales enquiry';content=`<div class="grid2">${field('customer','Customer / Company','text',row.customer,{required:true})}${field('brand_id','Distribution brand','select',row.brand_id, {options:brands(),required:true})}</div>${field('subject','Product / Project requirement','text',row.subject,{required:true})}<div class="grid3">${field('estimated_value','Estimated value (OMR)','number',row.estimated_value??0,{min:0,step:'.001'})}${field('stage','Pipeline stage','select',row.stage||'New',{options:['New','Qualified','Quoted','Negotiation','Won','Lost']})}${field('priority','Priority','select',row.priority||'Medium',{options:['Low','Medium','High','Urgent']})}</div><div class="grid2">${field('assigned_to','Sales owner','select',row.assigned_to||S.user.id,{options:users()})}${field('next_followup','Next follow-up','date',row.next_followup)}</div>${field('description','Requirement details / Notes','textarea',row.description,{placeholder:'Scope, requested quantity, specifications…'})}`}
 else if(type==='contact'){title=id?'Edit contact':'New customer / supplier';content=`<div class="grid2">${field('company','Company / Organization','text',row.company,{required:true})}${field('type','Contact category','select',row.type||'Customer',{options:['Customer','Supplier','Both']})}</div><div class="grid2">${field('contact_person','Contact person','text',row.contact_person)}${field('phone','Mobile / Office number','tel',row.phone)}</div>${field('email','Email address','email',row.email)}${field('notes','Notes','textarea',row.notes)}`}
 else if(type==='po'){title='Create purchase order';content=`<div class="notice info">PO reference numbers, totals and approval status are generated on the central database. New orders start as Draft.</div><div class="grid2">${field('vendor','Supplier / Vendor','text','',{required:true})}${field('brand_id','Distribution brand','select','',{options:brands(),required:true})}</div><div class="grid3">${field('currency','Currency','select','OMR',{options:['OMR','USD','AED','INR','EUR']})}${field('vat_percent','VAT %','number',5,{min:0,step:'.01'})}${field('delivery_date','Expected delivery date','date','')}</div>${field('enquiry_id','Linked sales enquiry','select','',{options:selectOpt(S.data.enquiries,'Not linked',true,x=>[x.id,x.enquiry_no+' — '+x.customer])})}<div class="panel-header" style="padding:8px 0 13px;margin:0 0 13px"><div class="panel-title">Items & quantities</div><button class="btn sm" type="button" data-action="add-po-line">${ico('plus',13)} Add line</button></div><div class="line-head"><span>Item / Description *</span><span>Qty *</span><span>Unit</span><span>Rate *</span><span></span></div><div id="poLines">${poLine()}</div><div class="grid2" style="margin-top:18px">${field('payment_terms','Payment terms','textarea','30% advance, balance before shipment')}${field('notes','Order notes','textarea','')}</div>`}
 else if(type==='doc'){title='Upload technical document';content=`<div class="grid2">${field('brand_id','Distribution brand','select','',{options:brands(),required:true})}${field('document_type','Document type','select','TDS',{options:['TDS','SDS','Catalogue','Certificate','Other']})}</div><div class="grid2">${field('title','Title / Material name','text','',{required:true})}${field('product','Product / Grade','text','')}</div>${field('version','Revision / Date reference','text','')}<div class="form-field"><label>Select TDS / PDF / Catalogue *</label><input type="file" name="upload_file" accept=".pdf,.png,.jpg,.jpeg,.doc,.docx,.xls,.xlsx" required><small class="hint">Maximum 20 MB. Private cloud storage, accessible only to permitted employees.</small></div>`}
 else if(type==='meeting'){title=id?'Update meeting':'Schedule a meeting';let local=row.starts_at?new Date(row.starts_at):new Date(Date.now()+86400000);const localTime=local.getFullYear()+'-'+String(local.getMonth()+1).padStart(2,'0')+'-'+String(local.getDate()).padStart(2,'0')+'T'+String(local.getHours()).padStart(2,'0')+':'+String(local.getMinutes()).padStart(2,'0');content=`<div class="grid2">${field('title','Meeting title','text',row.title,{required:true})}${field('meeting_type','Meeting type','select',row.meeting_type||'Customer',{options:['Customer','Supplier','Internal','Site Visit','Online']})}</div><div class="grid2">${field('starts_at','Meeting date & time','datetime-local',localTime,{required:true})}${field('assigned_to','Meeting owner','select',row.assigned_to||S.user.id,{options:users()})}</div><div class="grid2">${field('company','Company / Client','text',row.company)}${field('location','Location / Video link','text',row.location)}</div>${field('attendees','Attendees','text',row.attendees)}${field('agenda','Agenda / Meeting notes','textarea',row.agenda)}${field('status','Status','select',row.status||'Scheduled',{options:['Scheduled','Completed','Cancelled']})}${id?field('outcome','Meeting outcome','textarea',row.outcome):''}`}
 else if(type==='task'){title=id?'Edit follow-up':'Create follow-up';content=`${field('title','Action / Follow-up title','text',row.title,{required:true})}<div class="grid2">${field('related_type','Related to','select',row.related_type||'General',{options:['General','Enquiry','Purchase','Meeting','HR','Supplier']})}${field('related_ref','Related reference','text',row.related_ref)}</div><div class="grid2">${field('due_date','Due date','date',row.due_date||today())}${field('assigned_to','Assigned person','select',row.assigned_to||S.user.id,{options:users()})}</div><div class="grid2">${field('priority','Priority','select',row.priority||'Medium',{options:['Low','Medium','High','Urgent']})}${field('status','Status','select',row.status||'Open',{options:['Open','In Progress','Completed','Cancelled']})}</div>${field('notes','Task notes','textarea',row.notes)}`}
 else if(type==='employee'){title=id?'Edit employee':'Add employee';content=`<div class="grid2">${field('employee_no','Employee ID','text',row.employee_no,{required:true})}${field('full_name','Full name','text',row.full_name,{required:true})}</div><div class="grid2">${field('department','Department / Division','text',row.department||'Operations')}${field('designation','Designation','text',row.designation)}</div><div class="grid2">${field('work_email','Work email','email',row.work_email)}${field('phone','Contact number','tel',row.phone)}</div><div class="grid2">${field('joining_date','Joining date','date',row.joining_date)}${field('employment_status','Employment status','select',row.employment_status||'Active',{options:['Active','On Leave','Exited']})}</div>${field('notes','HR notes','textarea',row.notes)}`}
 else if(type==='leave'){title='Request leave';content=`<div class="notice info">Leave request will be submitted under your login: ${esc(S.profile.full_name)}. Only HR/Management can review approvals.</div><div class="grid2">${field('leave_type','Leave type','select','Annual',{options:['Annual','Sick','Emergency','Unpaid','Other']})}${field('start_date','From date','date',today(),{required:true})}</div>${field('end_date','To date','date',today(),{required:true})}${field('reason','Reason','textarea','')}`}
 else if(type==='brand'){title='Register a distribution brand';content=`${field('name','Brand name','text','',{required:true})}${field('category','Product category','text','',{placeholder:'Waterproofing, Coatings, Industrial Supplies…'})}`}
 else if(type==='profile'){title='Edit staff access';content=`<div class="notice">Access changes take effect on employees’ next refresh. Only Admin accounts can modify permission assignments.</div>${field('full_name','Employee name','text',row.full_name,{required:true})}<div class="grid2">${field('department','Department','select',row.department,{options:['sales','purchase','hr','management']})}${field('role','Access role','select',row.role,{options:['staff','manager','admin']})}</div>${field('active','Account status','select',String(row.active),{options:[['true','Active'],['false','Disabled']]})}<div class="hint">Login email: ${esc(row.email)} (managed in Supabase Authentication)</div>`}
 const overlay=document.getElementById('overlay');if(!overlay)return;overlay.innerHTML=`<div class="backdrop" id="modalBackdrop"><div class="modal ${type==='po'?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-title"><strong>${esc(title)}</strong><button class="icon-btn" data-action="close-modal" aria-label="Close">${ico('close',20)}</button></div><form id="recordForm" data-kind="${type}" data-id="${esc(id||'')}"><div class="modal-inner">${content}</div><div class="modal-foot">${btn('close-modal','Cancel','sm') }<button type="submit" class="btn gold">${ico(type==='doc'?'upload':'check',15)} ${type==='po'?'Generate draft PO':type==='doc'?'Upload privately':'Save record'}</button></div></form></div></div>`}
function poLine(){return `<div class="po-line"><input name="item_name" type="text" placeholder="Material description" required><input name="quantity" type="number" min="0.001" step="0.001" value="1" required><input name="unit" type="text" value="Nos"><input name="unit_price" type="number" min="0" step=".001" value="0" required><button type="button" class="icon-btn" data-action="remove-po-line" title="Remove">${ico('close',15)}</button></div>`}
function closeModal(){S.modal='';S.modalId=null;let e=document.getElementById('overlay');if(e)e.innerHTML=''}
function readForm(form){let data=Object.fromEntries(new FormData(form).entries());for(let [k,v] of Object.entries(data)){if(typeof v==='string')data[k]=v.trim();if(v==='')data[k]=null}return data}
async function saveForm(form){let type=form.dataset.kind,id=form.dataset.id,data=readForm(form),table=TYPE_TABLE[type];if(type==='po'){let lines=[...form.querySelectorAll('.po-line')].map(e=>Object.fromEntries([...e.querySelectorAll('input')].map(x=>[x.name,x.value.trim()])));if(!lines.length)throw Error('Add at least one order line');let obj={vendor:data.vendor,brand_id:data.brand_id,enquiry_id:data.enquiry_id,currency:data.currency,vat_percent:Number(data.vat_percent),delivery_date:data.delivery_date,payment_terms:data.payment_terms,notes:data.notes};let r=await createPO(obj,lines);toast(`Purchase order ${r?.po_no||''} created as Draft`);S.view='purchases'}
 else if(type==='doc'){let file=form.querySelector('[name="upload_file"]').files[0];if(!file)throw Error('Choose a document first');await uploadDocument({brand_id:data.brand_id,title:data.title,product:data.product,document_type:data.document_type,version:data.version},file);toast('Document metadata saved and file uploaded securely');S.view='documents'}
 else if(type==='leave'){if(data.end_date<data.start_date)throw Error('End date must be after start date');await insert('leave_requests',{...data,employee_id:S.user.id,status:'Pending'});toast('Leave request submitted for HR review');S.view='leaves'}
 else {if(type==='enquiry')data.estimated_value=Number(data.estimated_value||0);if(type==='meeting'&&data.starts_at)data.starts_at=new Date(data.starts_at).toISOString();if(type==='profile')data.active=data.active==='true';if(type==='enquiry'&&data.brand_id==null)throw Error('Please select a brand');if(['contact','enquiry','task','meeting','employee'].includes(type)&&!id)data.created_by=S.user.id;if(type==='profile'&&!id)throw Error('Profile must already exist');if(id)await update(table,id,data);else await insert(table,data);toast(`${type[0].toUpperCase()+type.slice(1)} ${id?'updated':'saved'} successfully`)}closeModal();render()}
function poDetails(id){const p=S.data.purchase_orders.find(x=>x.id===id);if(!p)return;let ls=S.data.purchase_order_lines.filter(l=>l.purchase_order_id===id),next={Draft:'Submitted',Submitted:'Approved',Approved:'Ordered',Ordered:'Partially Received','Partially Received':'Received'}[p.status],allowedNext=access(['purchase'])&&(next!=='Approved'||approver());const overlay=document.getElementById('overlay');overlay.innerHTML=`<div class="backdrop"><div class="modal wide"><div class="modal-title"><strong>Purchase order · ${esc(p.po_no)}</strong><button class="icon-btn" data-action="close-modal">${ico('close',20)}</button></div><div class="modal-inner"><div class="grid2"><div><div class="eyebrow">SUPPLIER / VENDOR</div><h3>${esc(p.vendor)}</h3><p class="hint">Distribution brand: ${esc(brandName(p.brand_id))}</p></div><div><div class="eyebrow">ORDER SUMMARY</div><h3>${badge(p.status)}</h3><p class="hint">${date(p.order_date)} · Delivery ${date(p.delivery_date)}</p></div></div>${dataTable(['Product / Description','Quantity','Unit','Rate','Line total'],ls.map(l=>tr(esc(l.item_name),Number(l.quantity).toFixed(3),esc(l.unit),money(l.unit_price,p.currency),money(l.line_total,p.currency))))}<div style="max-width:280px;margin:18px 0 0 auto;text-align:right"><div class="progress-info"><strong>Subtotal</strong><span>${money(p.subtotal,p.currency)}</span></div><div class="progress-info"><strong>VAT ${esc(p.vat_percent)}%</strong><span>${money(p.total-p.subtotal,p.currency)}</span></div><div class="progress-info" style="font-size:16px"><strong>Order Total</strong><strong>${money(p.total,p.currency)}</strong></div></div><div class="wide-note"><div>${ico('file',20)}</div><div><div class="panel-title">Payment terms</div><p style="font-size:12px;color:#73819b;white-space:pre-wrap">${esc(p.payment_terms||'Not specified')}</p><div class="hint">${esc(p.notes||'')}</div></div></div>${p.approved_by?`<p class="hint">Approved by ${esc(personName(p.approved_by))} on ${datetime(p.approved_at)}</p>`:''}</div><div class="modal-foot">${btn('print-po',ico('printer',14)+' Print / PDF','sm',id)}${allowedNext?btn('po-status',ico('check',14)+' Mark '+next,'gold',id,`data-value="${esc(next)}"`):''}${access(['purchase'])&&['Draft','Submitted'].includes(p.status)?btn('po-status','Cancel PO','sm danger',id,`data-value="Cancelled"`):''}</div></div></div>`}
async function printPO(id){let p=S.data.purchase_orders.find(x=>x.id===id);if(!p)return;let ls=S.data.purchase_order_lines.filter(x=>x.purchase_order_id===id);const html=`<!doctype html><html><head><meta charset="utf-8"><title>${esc(p.po_no)}</title><style>body{font-family:Arial;padding:35px;color:#25334c}header{border-bottom:4px solid #FF9A00;display:flex;align-items:center;gap:18px;padding-bottom:18px}header img{height:56px;width:auto}h1{font-size:20px}small{color:#8792a6}.grid{display:flex;justify-content:space-between;margin:30px 0;line-height:1.8}table{width:100%;border-collapse:collapse;margin:25px 0;font-size:12px}td,th{border:1px solid #dce2ed;padding:12px;text-align:left}th{background:#f6f7fa}footer{margin-top:65px;display:flex;justify-content:space-between}.right{text-align:right}.summary{width:230px;margin-left:auto}.status{border:1px solid #bcc7d9;padding:7px 14px;border-radius:5px}@media print{button{display:none}}</style></head><body><header><img src="${new URL(A.lockup,location.href).href}"><div><h1>AAARON COMMERCIAL SERVICES LLC</h1><small>Purchasing Department · Sultanate of Oman</small></div></header><div class="grid"><div><strong>SUPPLIER</strong><div>${esc(p.vendor)}</div><small>Brand: ${esc(brandName(p.brand_id))}</small></div><div class="right"><h2>PURCHASE ORDER</h2><strong>${esc(p.po_no)}</strong><div>Date: ${date(p.order_date)}</div><div>Delivery: ${date(p.delivery_date)}</div><div>Status: ${esc(p.status)}</div></div></div><table><thead><tr><th>#</th><th>Item / Description</th><th>Qty</th><th>Unit</th><th>Unit Price</th><th>Total</th></tr></thead><tbody>${ls.map((l,i)=>`<tr><td>${i+1}</td><td>${esc(l.item_name)}</td><td>${Number(l.quantity).toFixed(3)}</td><td>${esc(l.unit)}</td><td>${money(l.unit_price,p.currency)}</td><td>${money(l.line_total,p.currency)}</td></tr>`).join('')}</tbody></table><div class="summary"><p>Subtotal: <strong>${money(p.subtotal,p.currency)}</strong></p><p>VAT (${esc(p.vat_percent)}%): <strong>${money(p.total-p.subtotal,p.currency)}</strong></p><h3>TOTAL: ${money(p.total,p.currency)}</h3></div><p><strong>Payment terms:</strong><br>${esc(p.payment_terms||'—')}</p><p><strong>Notes:</strong> ${esc(p.notes||'—')}</p><footer><div>____________________<br>Prepared By</div><div>____________________<br>Authorized Approval${p.approved_by?`<br><small>${esc(personName(p.approved_by))}</small>`:''}</div></footer><p style="text-align:center;margin-top:40px;color:#9da6b6;font-size:10px">Generated from AAARON OneWork CRM · ${new Date().toLocaleString('en-GB')}</p><script>window.onload=()=>setTimeout(()=>window.print(),350)<\/script></body></html>`;let popup=window.open('','_blank');if(!popup){toast('Please allow pop-ups to print this purchase order',true);return}popup.document.open();popup.document.write(html);popup.document.close()}
function csvExport(rows,filename){if(!rows.length){toast('No records to export',true);return}const cols=Object.keys(rows[0]);const clean=(val)=>{let v=String(val??'').replaceAll('"','""');if(/^[\s]*[=+@\-\t\r]/.test(v)&&typeof val!=='number')v="'"+v;return '"'+v+'"'};let csv='\ufeff'+cols.map(clean).join(',')+'\r\n'+rows.map(r=>cols.map(k=>clean(r[k])).join(',')).join('\r\n');let url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));let a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function reportExport(){let data=S.view==='reports'?S.data.brands.map(b=>({Brand:b.name,Enquiries:S.data.enquiries.filter(e=>e.brand_id===b.id).length,Sales_Value_OMR:S.data.enquiries.filter(e=>e.brand_id===b.id).reduce((s,x)=>s+Number(x.estimated_value||0),0),POs:S.data.purchase_orders.filter(p=>p.brand_id===b.id).length,TDS_Documents:S.data.technical_documents.filter(d=>d.brand_id===b.id).length})):S.data[({enquiries:'enquiries',purchases:'purchase_orders',contacts:'contacts',tasks:'tasks',employees:'employees'})[S.view]||'enquiries'];csvExport(data,'AAARON_'+S.view+'_'+today()+'.csv')}
async function handleAuth(form){if(!configured()){S.authError='Supabase is not configured yet. Use the demo or follow GO_LIVE_SETUP.md.';renderAuth();return}if(!S.sb && !await ensureSDK()){S.authError='Could not connect to Supabase. Check internet and configuration.';renderAuth();return}let fd=Object.fromEntries(new FormData(form).entries());try{S.authError='';if(S.authPanel==='newpassword'){if(fd.password.length<8)throw Error('Use at least 8 characters');if(fd.password!==fd.confirm)throw Error('Passwords do not match');let r=await S.sb.auth.updateUser({password:fd.password});if(r.error)throw r.error;toast('Password updated. Your session is now active.');S.authPanel='login';if(r.data?.user)await enterLive(r.data.user);else renderAuth();return}if(S.authPanel==='login'){let {error}=await S.sb.auth.signInWithPassword({email:fd.email,password:fd.password});if(error)throw error}else if(S.authPanel==='signup'){let {data,error}=await S.sb.auth.signUp({email:fd.email,password:fd.password,options:{data:{full_name:fd.full_name}}});if(error)throw error;toast(data?.session?'Account created. Ask your admin to assign department access.':'Check your email to confirm registration. Then ask an admin to assign your department.');S.authPanel='login';renderAuth()}else{let {error}=await S.sb.auth.resetPasswordForEmail(fd.email,{redirectTo:location.origin+location.pathname});if(error)throw error;toast('Check your email for the reset link.');S.authPanel='login';renderAuth()}}catch(e){S.authError=e.message||'Authentication failed';renderAuth()}}
async function handleClick(e){let nav=e.target.closest('[data-nav]');if(nav){S.view=nav.dataset.nav;S.query='';S.filter='All';OW.onNav.forEach(f=>f(S.view));render();window.scrollTo(0,0);return}let b=e.target.closest('[data-action]');if(!b)return;let a=b.dataset.action,id=b.dataset.id,val=b.dataset.value;try{if(a==='menu'){S.mobile=!S.mobile;document.querySelector('.sidebar')?.classList.toggle('open');return}if(a==='demo'){enterDemo();return}if(a==='retry'){await enterLive(S.user);return}if(a==='logout'){if(S.mode==='demo'){S.mode='auth';S.authPanel='login';S.user=null;render();return}await S.sb?.auth.signOut();S.mode='auth';S.user=null;S.profile=null;S.authPanel='login';S.sub?.unsubscribe();render();return}if(a==='auth-mode'){S.authPanel=val;S.authError='';renderAuth();return}if(a==='close-modal'){closeModal();return}if(a==='add-po-line'){document.getElementById('poLines')?.insertAdjacentHTML('beforeend',poLine());return}if(a==='remove-po-line'){let ls=document.querySelectorAll('.po-line');if(ls.length<=1){toast('At least one order line is required',true);return}b.closest('.po-line')?.remove();return}if(a==='brand-filter'){S.filter=id;render();return}if(a==='prev-month'){S.month=new Date(S.month.getFullYear(),S.month.getMonth()-1,1);render();return}if(a==='next-month'){S.month=new Date(S.month.getFullYear(),S.month.getMonth()+1,1);render();return}if(a==='select-date'){S.selectedDate=id;render();return}if(a==='export'){reportExport();return}if(a==='print-report'){window.print();return}if(a==='refresh'){if(S.mode==='live')await loadAll();render();toast('Workspace refreshed');return}if(a==='reset-demo'){if(!confirm('Reset all demo records?'))return;S.data=demoSeed();persistDemo();render();toast('Demo reset');return}if(a==='open-doc'){await openDocument(id);return}if(a==='print-po'){await printPO(id);return}if(a==='po-details'){poDetails(id);return}if(a==='po-status'){if(!confirm(`Change PO status to ${val}?`))return;await setPO(id,val);closeModal();render();toast('Purchase order status updated');return}if(a==='approve-leave'||a==='reject-leave'){await reviewLeave(id,a==='approve-leave'?'Approved':'Rejected');render();toast('Leave request reviewed');return}let match=a.match(/^(new|edit)-(enquiry|contact|po|doc|meeting|task|employee|candidate|leave|brand|profile)$/);if(match){modalOpen(match[2],match[1]==='edit'?id:null);return}}catch(err){console.error(err);toast(err.message||'Operation failed',true)}}
function handleInput(e){if(e.target.id==='searchRecords'){let start=e.target.selectionStart;S.query=e.target.value;render();let i=document.getElementById('searchRecords');i?.focus();try{i?.setSelectionRange(start,start)}catch{}}}
function handleChange(e){if(e.target.id==='filterRecords'){S.filter=e.target.value;render()}}
function handleSubmit(e){if(e.target.id==='authForm'){e.preventDefault();handleAuth(e.target);return}if(e.target.id!=='recordForm')return;e.preventDefault();let b=e.target.querySelector('button[type="submit"]');if(b){b.disabled=true;b.textContent='Saving…'}saveForm(e.target).catch(err=>{console.error(err);toast(err.message||'Could not save record',true);if(b){b.disabled=false;b.textContent='Try save again'}})}
