function extTechnicalView(){let arr=extFiltered(S.data.technical_actions||[],a=>[a.title,a.customer,a.action_type,a.status,a.system_name].join(' '));return `${extHeader('Technical approvals & field execution','Track mock-up trials, consultant submissions, tender BOQs and won application jobs.','Create record','technical')}${extToolbar()}<div class="ext-stats">${['Mock-up','Approval','Tender','Application Job'].map((k,i)=>metric(k,(S.data.technical_actions||[]).filter(x=>x.action_type===k).length,'Active & historical records',['check','shield','file','box'][i],['gold','blue','green','gold'][i])).join('')}</div>${dataTable(['Reference / customer','Type / system','Status','Due','Actions'],arr.map(a=>tr(`${extCell(a.title)}<div class="hint">${extString(a.customer)}</div>`,`${badge(a.action_type)}<div class="hint">${extString(a.system_name)}</div>`,badge(a.status),date(a.due_date),btn('ext-edit','Update','sm',a.id,'data-value="technical"'))),'No technical actions yet')}`;}
function extTargetView(){let arr=S.data.sales_targets||[],cr=S.data.trader_credit||[],traders=S.data.contacts.filter(c=>c.trader_category);return `${isSalesManager()?extHeader('Sales targets & trade network','Review salesperson activity goals, distributor relationships, pricing and customer credit flags.','Set target','target'):layoutHead('Sales targets & trade network','Targets set by management, visible to authorized sales staff.','')}${extToolbar()}<div class="ext-stats">${metric('Active trade accounts',traders.length,'Distributor, sub-distributor and retailer','users','blue')}${metric('Goals assigned',arr.length,'Monthly or quarterly targets','chart','gold')}${metric('Credit reviews',cr.filter(x=>x.status==='Watch'||x.status==='Blocked').length,'Management-only financial settings','shield','red')}</div>${dataTable(['Target for','Period','Sales target','Visit target','Edit'],arr.map(t=>tr(extCell(t.target_name),extString(t.period),money(t.target_value),extString(t.target_visits||0),btn('ext-edit','Edit','sm',t.id,'data-value="target"'))),'No targets configured')}<div class="section-gap"></div><div class="panel-title" style="margin:12px 0">Trade customer directory</div>${dataTable(['Company','Category','Parent network','Price tier / credit status','Details'],traders.map(c=>tr(extCell(c.company),badge(c.trader_category),extString(c.parent_company||'Independent'),`${extString(c.pricing_tier)} · ${badge(c.credit_status||'Not set')}`,btn('edit-contact','Edit','sm',c.id))),'No trade customers assigned yet')}`;}
function extInsightView(){let {open,won,lost,weighted,value}=extCounts(),act=S.data.sales_activities||[],winPct=(won.length+lost.length)?(won.length/(won.length+lost.length)*100).toFixed(1):'—',byChannel=['Project','Trade','Counter','Application'].map(c=>({channel:c,items:open.filter(x=>x.channel===c),won:won.filter(x=>x.channel===c)}));let losses=Object.entries(lost.reduce((o,x)=>(o[x.lost_reason||'Not given']=(o[x.lost_reason||'Not given']||0)+1,o),{}));const now=today();return `${layoutHead('Sales intelligence','Executive forecast, pipeline health, channel performance and employee effort.','')}${btn('ext-export',ico('download',14)+' Export Opportunities','sm')}<div class="ext-stats">${metric('Open pipeline',money(value),'All active opportunities','chart','blue')}${metric('Weighted forecast',money(weighted),'Probability-adjusted OMR','chart','gold')}${metric('Win rate',winPct==='—'?'—':winPct+'%','Closed won / closed total','check','green')}${metric('Activity logs',act.length,'Customer-facing activities','users','blue')}</div><div class="ext-split"><div class="panel ext-panel"><h3>Pipeline by sales channel</h3>${byChannel.map(c=>`<div class="ext-barline"><div><strong>${c.channel}</strong><span>${c.items.length} open · ${money(c.items.reduce((s,x)=>s+extNum(x.estimated_value),0))}</span></div><div class="ext-bartrack"><i style="width:${value?Math.min(100,c.items.reduce((s,x)=>s+extNum(x.estimated_value),0)/value*100):0}%"></i></div></div>`).join('')}</div><div class="panel ext-panel"><h3>Action needed</h3>${open.filter(o=>o.next_followup&&o.next_followup<=now).slice(0,6).map(o=>`<div class="ext-action"><strong>${extString(o.title)}</strong><small>${extString(o.customer)} · ${date(o.next_followup)}</small></div>`).join('')||'<p class="hint">No follow-ups overdue today.</p>'}<h3 style="margin-top:18px">Lost reasons</h3>${losses.map(([reason,n])=>`<p class="ext-loss">${extString(reason)} <strong>${n}</strong></p>`).join('')||'<p class="hint">No lost opportunities in current records.</p>'}</div></div><div class="panel ext-panel" style="margin-top:18px"><h3>Sales team activity</h3>${dataTable(['Staff member','Meetings & calls','Site / shop visits','Mock-ups','Open opportunities'],S.data.profiles.filter(x=>x.department==='sales').map(p=>{let userActs=act.filter(a=>a.owner_id===p.id);return tr(extCell(p.full_name),userActs.filter(a=>['Meeting','Phone Call','Email','WhatsApp'].includes(a.activity_type)).length,userActs.filter(a=>['Site Visit','Trader Shop Visit'].includes(a.activity_type)).length,userActs.filter(a=>a.activity_type==='Mock-up').length,open.filter(o=>o.owner_id===p.id).length)}),'No salespeople found')}</div>`;}
function extConnectionsView(){return `${layoutHead('Communication centre','Connect customer conversations to the same customer/project record, with privacy and consent controls.','')}<div class="notice info"><strong>Connection status:</strong> Gmail and WhatsApp Business automatic synchronization are not active in this installation. Use the working compose links and manual activity logs below. Automatic two-way synchronization requires separately authorized business integrations.</div><div class="ext-conn-grid"><div class="panel ext-panel"><div class="conn-logo">✉️</div><h3>Company email</h3><p>Open a drafted email to a customer, send through your preferred email app and log the activity in the CRM.</p><div class="hint">Full Gmail/Outlook two-way history: requires connection</div>${btn('ext-new','Log email activity','gold','','data-value="activity"')}</div><div class="panel ext-panel"><div class="conn-logo">💬</div><h3>WhatsApp Business</h3><p>Launch a customer chat from their business contact record. Copy critical decisions into the CRM activity timeline.</p><div class="hint">Automatic WhatsApp chat synchronization: requires an approved business integration</div>${btn('ext-new','Log WhatsApp follow-up','gold','','data-value="activity"')}</div><div class="panel ext-panel"><div class="conn-logo">📅</div><h3>Meeting calendar</h3><p>Schedule internal or external meetings in OneWork. Download calendar invites for Outlook, Google Calendar or other calendar apps.</p><div class="hint">Live Google/Outlook bidirectional synchronization: not yet connected</div>${btn('new-meeting','Schedule meeting','gold')}</div></div><div class="panel ext-panel" style="margin-top:18px"><h3>Customer communications</h3>${dataTable(['Company','Email','WhatsApp','Log'],S.data.contacts.filter(c=>c.type!=='Supplier').slice(0,45).map(c=>tr(extCell(c.company),c.email?btn('ext-email','Compose email','sm',c.id):'—',c.phone?btn('ext-whatsapp','Open WhatsApp','sm',c.id):'—',btn('ext-new','Log activity','sm','','data-value="activity"'))),'Add a customer with email or phone to enable communication links.')}</div>`;}
const baseView=view;
view=function(){if(OW.views[S.view])return OW.views[S.view]();switch(S.view){case 'projects':return extProjectsView();case'opportunities':return extOpView();case'quotations':return extQuoteView();case'products':return extProductView();case'activities':return extActivityView();case'technical':return extTechnicalView();case'targets':return extTargetView();case'insights':return extInsightView();case'connections':return extConnectionsView();default:return baseView()}};
const baseMeetings=meetings;
meetings=function(){return baseMeetings()+`<div class="panel ext-panel" style="margin-top:10px"><h3>Export meeting appointments</h3><p class="hint">Download a standard .ics file to import into Google Calendar or Outlook. This is a one-way export, not automatic calendar synchronization.</p>${btn('ext-calendar','Download calendar file (.ics)','sm')}</div>`};
function exportMeetingCalendar(){const safe=s=>String(s||'').replace(/\\/g,'\\\\').replace(/,/g,'\\,').replace(/;/g,'\\;').replace(/\n/g,'\\n');const stamp=s=>new Date(s).toISOString().replace(/[-:]/g,'').split('.')[0]+'Z';const rows=(S.data.meetings||[]).filter(m=>m.starts_at).map(m=>['BEGIN:VEVENT','UID:'+m.id+'@aaaron-onework','DTSTAMP:'+stamp(new Date().toISOString()),'DTSTART:'+stamp(m.starts_at),'DTEND:'+stamp(new Date(new Date(m.starts_at).getTime()+3600000).toISOString()),'SUMMARY:'+safe(m.title),'DESCRIPTION:'+safe(m.agenda),'LOCATION:'+safe(m.location),'END:VEVENT'].join('\r\n'));const text=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//AAARON OneWork//CRM//EN',...rows,'END:VCALENDAR'].join('\r\n');const url=URL.createObjectURL(new Blob([text],{type:'text/calendar'}));const a=document.createElement('a');a.href=url;a.download='AAARON_Meetings_'+today()+'.ics';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
const baseDashboard=dashboard;
dashboard=function(){let c=extCounts(),st=S.data.technical_actions||[];return baseDashboard()+`<div class="section-gap"></div><div class="ext-section-head"><h2>Commercial intelligence</h2>${btn('ext-jump','Open Sales intelligence','sm','','data-value="insights"')}</div><div class="ext-stats">${metric('Opportunity pipeline',money(c.value),'Project, Trade, Counter & Applications','chart','gold')}${metric('Weighted sales forecast',money(c.weighted),'Probability-adjusted','chart','green')}${metric('Project accounts',extProjects().length,'Site and stakeholder tracking','box','blue')}${metric('Technical submissions',st.length,'Mock-ups, approvals, tenders','file','gold')}</div>`;};
const baseContacts=contacts;
contacts=function(){let arr=extFiltered(S.data.contacts||[],c=>[c.company,c.customer_no,c.contact_person,c.phone,c.sales_channel,c.trader_category].join(' '));return `${layoutHead('Customer & trade master','Permanent customer numbers, parent distributors, pricing groups and a single customer contact history.',btn('new-contact',ico('plus',15)+' Add customer / supplier','gold'))}${extToolbar()}<div class="panel">${dataTable(['Customer ID / company','Channel / category','Contact','Trade details','Communication / edit'],arr.map(c=>tr(`<strong>${extString(c.company)}</strong><div class="hint">${extString(c.customer_no||'Pending ID')} · ${extString(c.cr_no||'')}</div>`,`${badge(c.sales_channel||'Project')} ${c.trader_category?badge(c.trader_category):''}`,`${extString(c.contact_person)}<div class="hint">${extString(c.phone)} · ${extString(c.email)}</div>`,`${extString(c.pricing_tier||'Standard')}<div class="hint">${extString(c.parent_company||'')} ${c.credit_status? '· '+extString(c.credit_status):''}</div>`,`${c.email?btn('ext-email','Email','sm',c.id):''} ${c.phone?btn('ext-whatsapp','WhatsApp','sm',c.id):''} ${btn('edit-contact','Edit','sm',c.id)}`)),'No customers yet')}</div>`;};
const baseReports=reports;
reports=function(){return baseReports()+`<div class="section-gap"></div><div class="ext-section-head"><h2>Advanced sales pipeline reports</h2>${btn('ext-jump','Open full analysis','sm','','data-value="insights"')}</div><div class="ext-stats">${metric('Active Opportunities',extCounts().open.length,'Not closed','chart','blue')}${metric('Project forecast',money(extOps().filter(x=>x.channel==='Project').reduce((s,x)=>s+amountOMR(x)*extNum(x.probability)/100,0)),'Weighted project pipeline','chart','gold')}${metric('Sales activities',(S.data.sales_activities||[]).length,'Logged customer interactions','users','green')}</div>`;};

